//! Bucket fill parity (ex-704).
//!
//! `tests/fixtures/bucket-fill.json` is upstream's own
//! `packages/element/src/bucketFill.ts` at the pinned commit, generated by
//! `tools/goldens/bucket-fill-fixtures.mjs`: every call
//! `packages/element/tests/bucketFill.test.ts` makes (the test run as
//! written, `upstream-*`) and seeded random scenes of closed and open
//! outlines (`random-*`), each with what upstream answered. Every call is
//! reproduced exactly: `computeBucketFillPolygon`'s owner, boundary ids,
//! scene points and insertion (or its failure reason), and
//! `isRestylableFill`.
//!
//! The tests after the replay restate a few of `bucketFill.test.ts`'s
//! assertions on the port directly.

use excali_core::element::Element;
use excali_editor::bucket_fill::{
    compute_bucket_fill_polygon, is_bucket_fill_compatible, is_restylable_fill,
    renders_opaque_fill, BucketFillFailureReason, BucketFillOptions, Placement,
};
use excali_scene::bounds::ElementsMap;
use serde_json::{json, Value};

const FIXTURE: &str = include_str!("fixtures/bucket-fill.json");

fn cases() -> Vec<Value> {
    let fixture: Value = serde_json::from_str(FIXTURE).expect("bucket-fill.json parses");
    fixture["cases"].as_array().expect("cases").clone()
}

fn element(value: &Value) -> Element {
    Element::from_map(value.as_object().expect("an element").clone())
        .expect("an element upstream built")
}

fn elements(call: &Value) -> Vec<Element> {
    call["elements"]
        .as_array()
        .expect("elements")
        .iter()
        .map(element)
        .collect()
}

fn point(value: &Value) -> [f64; 2] {
    [value[0].as_f64().expect("x"), value[1].as_f64().expect("y")]
}

fn points(value: &Value) -> Vec<[f64; 2]> {
    value.as_array().expect("points").iter().map(point).collect()
}

/// `{ ...DEFAULT_BUCKET_FILL_OPTIONS, ...options }`.
fn options(value: &Value) -> BucketFillOptions {
    let mut options = BucketFillOptions::default();
    let Some(given) = value.as_object() else {
        return options;
    };
    for (key, v) in given {
        let v = v.as_f64().expect("a number");
        match key.as_str() {
            "snapEpsilon" => options.snap_epsilon = v,
            "gapTolerance" => options.gap_tolerance = v,
            "minArea" => options.min_area = v,
            "maxBoundarySegments" => options.max_boundary_segments = v as usize,
            "maxGeneratedPoints" => options.max_generated_points = v as usize,
            "fallbackSearchRadius" => options.fallback_search_radius = v,
            other => panic!("unknown option {other}"),
        }
    }
    options
}

fn reason(value: &str) -> BucketFillFailureReason {
    match value {
        "no_owner" => BucketFillFailureReason::NoOwner,
        "open_region" => BucketFillFailureReason::OpenRegion,
        "too_complex" => BucketFillFailureReason::TooComplex,
        "too_small" => BucketFillFailureReason::TooSmall,
        "invalid_polygon" => BucketFillFailureReason::InvalidPolygon,
        other => panic!("unknown reason {other}"),
    }
}

/// What the port answered, in the fixture's JSON shape.
fn compute(call: &Value) -> Value {
    let scene = elements(call);
    let map = ElementsMap::new(scene.iter());
    let refs: Vec<&Element> = scene.iter().collect();
    match compute_bucket_fill_polygon(point(&call["point"]), &refs, &map, &options(&call["options"]))
    {
        Ok(fill) => json!({
            "ok": true,
            "ownerId": fill.owner_id,
            "boundaryElementIds": fill.boundary_element_ids,
            "scenePoints": fill.scene_points,
            "insertion": {
                "placement": match fill.insertion.placement {
                    Placement::Above => "above",
                    Placement::Below => "below",
                },
                "elementId": fill.insertion.element_id,
            },
        }),
        Err(reason) => json!({ "ok": false, "reason": reason.as_str() }),
    }
}

#[test]
fn replays_every_upstream_call() {
    let mut calls = 0;
    let mut failures = Vec::new();
    for case in cases() {
        let id = case["id"].as_str().expect("id");
        for (k, call) in case["calls"].as_array().expect("calls").iter().enumerate() {
            calls += 1;
            let (expected, actual) = match call["fn"].as_str().expect("fn") {
                "computeBucketFillPolygon" => (call["result"].clone(), compute(call)),
                "isRestylableFill" => {
                    let scene = elements(call);
                    let map = ElementsMap::new(scene.iter());
                    let hit = element(&call["hitElement"]);
                    let answer =
                        is_restylable_fill(&hit, &points(&call["scenePoints"]), &map);
                    (call["result"].clone(), Value::Bool(answer))
                }
                other => panic!("unknown fn {other}"),
            };
            if !same(&expected, &actual) {
                failures.push(format!(
                    "{id} call {k} ({}):\n  expected {}\n  actual   {}",
                    call["fn"],
                    truncate(&expected),
                    truncate(&actual)
                ));
            }
        }
    }
    assert!(calls > 700, "only {calls} calls in the fixture");
    assert!(
        failures.is_empty(),
        "{} of {calls} calls differ from upstream:\n{}",
        failures.len(),
        failures.iter().take(12).cloned().collect::<Vec<_>>().join("\n")
    );
}

/// JSON equality with numbers compared as doubles (upstream writes `0`, the
/// port `0.0`): every coordinate must be the same double.
fn same(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => x.as_f64() == y.as_f64(),
        (Value::Array(x), Value::Array(y)) => {
            x.len() == y.len() && x.iter().zip(y).all(|(x, y)| same(x, y))
        }
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len() && x.iter().all(|(k, v)| y.get(k).is_some_and(|w| same(v, w)))
        }
        _ => a == b,
    }
}

fn truncate(value: &Value) -> String {
    let text = value.to_string();
    if text.len() > 600 {
        format!("{}…", &text[..600])
    } else {
        text
    }
}

#[test]
fn the_fixture_covers_every_outcome() {
    let mut seen = std::collections::BTreeSet::new();
    for case in cases() {
        for call in case["calls"].as_array().expect("calls") {
            let result = &call["result"];
            if call["fn"] == "isRestylableFill" {
                seen.insert(format!("restylable-{result}"));
            } else if result["ok"] == true {
                let owner = if result["ownerId"].is_null() { "ownerless" } else { "owned" };
                let placement = result["insertion"]["placement"].as_str().expect("placement");
                seen.insert(format!("ok-{owner}"));
                seen.insert(format!("ok-{placement}"));
            } else {
                let reason = reason(result["reason"].as_str().expect("reason"));
                seen.insert(reason.as_str().to_string());
            }
        }
    }
    for outcome in [
        "ok-owned",
        "ok-ownerless",
        "ok-above",
        "ok-below",
        "no_owner",
        "open_region",
        "too_complex",
        "too_small",
        "invalid_polygon",
        "restylable-true",
        "restylable-false",
    ] {
        assert!(seen.contains(outcome), "no call with outcome {outcome}: {seen:?}");
    }
}

// -- bucketFill.test.ts's assertions, restated on the port -----------------------

fn rectangle(id: &str, x: f64, y: f64, w: f64, h: f64, extra: Value) -> Element {
    let mut value = json!({
        "id": id, "type": "rectangle", "x": x, "y": y, "width": w, "height": h,
        "angle": 0, "strokeColor": "#1e1e1e", "backgroundColor": "transparent",
        "fillStyle": "solid", "strokeWidth": 2, "strokeStyle": "solid", "roughness": 1,
        "opacity": 100, "groupIds": [], "frameId": null, "index": null, "roundness": null,
        "seed": 1, "version": 1, "versionNonce": 0, "isDeleted": false,
        "boundElements": null, "updated": 1, "link": null, "locked": false,
    });
    for (k, v) in extra.as_object().expect("extra") {
        value[k] = v.clone();
    }
    element(&value)
}

fn area(points: &[[f64; 2]]) -> f64 {
    let mut sum = 0.0;
    let n = points.len();
    for i in 0..n {
        let [x0, y0] = points[(i + n - 1) % n];
        let [x1, y1] = points[i];
        sum += (x0 + x1) * (y0 - y1);
    }
    (sum / 2.0).abs()
}

#[test]
fn fills_a_simple_rectangle_below_its_transparent_owner() {
    let rect = rectangle("r", 0.0, 0.0, 100.0, 100.0, json!({}));
    let map = ElementsMap::new([&rect]);
    let fill = compute_bucket_fill_polygon([50.0, 50.0], &[&rect], &map, &BucketFillOptions::default())
        .expect("a fill");
    assert_eq!(fill.owner_id.as_deref(), Some("r"));
    assert!(fill.boundary_element_ids.is_empty());
    assert_eq!(fill.insertion.placement, Placement::Below);
    assert_eq!(fill.insertion.element_id, "r");
    assert_eq!(fill.scene_points.first(), fill.scene_points.last());
    assert!((area(&fill.scene_points) - 10000.0).abs() < 5.0);
}

#[test]
fn open_canvas_has_no_owner() {
    let rect = rectangle("r", 0.0, 0.0, 100.0, 100.0, json!({}));
    let map = ElementsMap::new([&rect]);
    let result =
        compute_bucket_fill_polygon([500.0, 500.0], &[&rect], &map, &BucketFillOptions::default());
    assert_eq!(result.err(), Some(BucketFillFailureReason::NoOwner));
    let empty = ElementsMap::new([]);
    let result = compute_bucket_fill_polygon([0.0, 0.0], &[], &empty, &BucketFillOptions::default());
    assert_eq!(result.err(), Some(BucketFillFailureReason::NoOwner));
}

#[test]
fn a_fill_is_restylable_on_the_same_region_only() {
    let rect = rectangle("r", 0.0, 0.0, 100.0, 100.0, json!({}));
    let map = ElementsMap::new([&rect]);
    let fill = compute_bucket_fill_polygon([50.0, 50.0], &[&rect], &map, &BucketFillOptions::default())
        .expect("a fill");
    let [ox, oy] = fill.scene_points[0];
    let local: Vec<[f64; 2]> = fill.scene_points.iter().map(|[x, y]| [x - ox, y - oy]).collect();
    let (min_x, max_x) = local.iter().fold((f64::MAX, f64::MIN), |(a, b), p| (a.min(p[0]), b.max(p[0])));
    let (min_y, max_y) = local.iter().fold((f64::MAX, f64::MIN), |(a, b), p| (a.min(p[1]), b.max(p[1])));
    let paint = element(&json!({
        "id": "fill", "type": "line", "x": ox, "y": oy, "width": max_x - min_x,
        "height": max_y - min_y, "angle": 0, "strokeColor": "transparent",
        "backgroundColor": "#ffc9c9", "fillStyle": "solid", "strokeWidth": 1,
        "strokeStyle": "solid", "roughness": 0, "opacity": 100, "groupIds": [],
        "frameId": null, "index": null, "roundness": null, "seed": 1, "version": 1,
        "versionNonce": 0, "isDeleted": false, "boundElements": null, "updated": 1,
        "link": null, "locked": false, "points": local, "polygon": true,
        "lastCommittedPoint": null, "startBinding": null, "endBinding": null,
        "startArrowhead": null, "endArrowhead": null,
    }));
    assert!(is_bucket_fill_compatible(&paint));
    assert!(renders_opaque_fill(&paint));
    assert!(!renders_opaque_fill(&rect));
    let scene = [&rect, &paint];
    let map = ElementsMap::new(scene);
    assert!(is_restylable_fill(&paint, &fill.scene_points, &map));
    let half: Vec<[f64; 2]> = vec![[0.0, 0.0], [50.0, 0.0], [50.0, 100.0], [0.0, 100.0], [0.0, 0.0]];
    assert!(!is_restylable_fill(&paint, &half, &map));
    assert!(!is_restylable_fill(&rect, &fill.scene_points, &map));
}
